        "newsId": "art-te-004",
        "articleTitle": "నా ఫోన్ ట్యాప్ చేస్తున్నారు: రాహుల్ సంచలనం",
        "headlineHighlight": "ట్యాప్ చేస్తున్నారు",
        "subheadline": "ఇందులోనే ఆధారాలన్నీ ఉన్నాయి; చర్చకు సిద్ధమని ఇన్‌స్టా 'ఆస్క్ మీ' సెషన్లో మోదీకి సవాల్",
        "byline": "ప్రత్యేక ప్రతినిధి, న్యూఢిల్లీ",
        "category": "జాతీయం",
        "leadParagraph": "తన వ్యక్తిగత స్మార్ట్‌ఫోన్ నిరంతరం నిఘాలో ఉందని, హ్యాకింగ్ అలర్ట్‌లు వస్తున్నాయని కాంగ్రెస్ అగ్రనేత రాహుల్ గాంధీ సంచలన ఆరోపణ చేశారు.",
        "bodyContent": "ప్రతిపక్షాల నాయకుల గొంతు నొక్కేందుకు కేంద్ర దర్యాప్తు సంస్థలను, అత్యాధునిక నిఘా పరికరాలను దుర్వినియోగం చేస్తున్నారని రాహుల్ గాంధీ మండిపడ్డారు. దేశంలో పెగాసస్ తరహా స్పైవేర్ మళ్లీ క్రియాశీలకంగా మారిందని ఆరోపించారు. తన ఫోన్‌కు వచ్చిన హెచ్చరిక సందేశాలను బహిర్గతం చేస్తూ, ఈ అక్రమ నిఘా వ్యవహారంపై సుప్రీంకోర్టు సిట్టింగ్ న్యాయమూర్తితో స్వతంత్ర విచారణ జరిపించాలని డిమాండ్ చేశారు. ప్రజాస్వామ్య వ్యవస్థల స్వయంప్రతిపత్తిని కాపాడేందుకు ప్రజలంతా ఏకం కావాలని పిలుపునిచ్చారు. పార్లమెంట్‌లో ఈ వ్యవహారంపై సమగ్ర చర్చకు ప్రభుత్వం సిద్ధమా అని ప్రధానికి సవాల్ విసిరారు.",
