        "articleTitle": "హైదరాబాద్ కొత్త సీపీగా మహేష్ భగవత్",
        "subheadline": "శాంతిభద్రతల పరిరక్షణలో ఫ్రెండ్లీ పోలీసింగ్‌కు అత్యున్నత ప్రాధాన్యం",
        "byline": "క్రైమ్ రిపోర్టర్, హైదరాబాద్",
        "category": "సిటీ",
        "leadParagraph": "హైదరాబాద్ నగర పోలీస్ కమిషనర్‌గా సీనియర్ ఐపీఎస్ అధికారి మహేష్ భగవత్ శనివారం అధికారికంగా బాధ్యతలు స్వీకరించారు.",
        "bodyContent": "నగరంలో శాంతిభద్రతల పరిరక్షణ, మహిళల రక్షణ, సైబర్ నేరాల కట్టడికి ప్రత్యేక టాస్క్‌ఫోర్స్ విభాగాలను ఏర్పాటు చేయనున్నట్లు నూతన సీపీ ప్రకటించారు. డ్రగ్స్ రహిత నగరంగా తీర్చిదిద్దడమే పోలీస్ శాఖ ప్రధాన ధ్యేయమని స్పష్టం చేశారు. ప్రతి పోలీస్ స్టేషన్‌లో ఫ్రెండ్లీ పోలీసింగ్ సిటిజన్ డెస్క్‌లు అందుబాటులోకి తెస్తామని తెలిపారు. రాత్రి వేళల్లో పెట్రోలింగ్ ముమ్మరం చేసి నేరాలను అదుపు చేస్తామన్నారు.",
