        "bodyContent": "ప్రమాద బీమా, ఉచిత ఈఎస్‌ఐ సౌకర్యం కల్పించడంతో పాటు రూ. 220 కోట్లతో డ్రైవర్ల సంక్షేమ బోర్డు ఏర్పాటు చేస్తున్నామని మంత్రి స్పష్టం చేశారు. లైసెన్సులు, వాహన ఫిట్‌నెస్ పునరుద్ధరణలో ప్రత్యేక వెసులుబాట్లు కల్పిస్తామన్నారు. పిల్లల ఉన్నత విద్యా రుణాలు, ఆరోగ్య రక్షణకు కార్పస్ ఫండ్ ఏర్పాటు చేసి అండగా ఉంటామని భరోసా ఇచ్చారు.",
