        "bodyContent": "పొగమంచు కారణంగా దృశ్యమానత తీవ్రంగా తగ్గి ఎదురుగా వేగంగా వస్తున్న కంటైనర్ ట్రక్కును బస్సు బలంగా ఢీకొట్టింది. ప్రమాద సమాచారం అందుకున్న వెంటనే పోలీసులు సంఘటనా స్థలానికి చేరుకుని సహాయక చర్యలు ముమ్మరం చేశారు. క్షతగాత్రులను గౌహతి ఆసుపత్రికి తరలించి అత్యవసర చికిత్స అందిస్తున్నారు. మృతుల కుటుంబాలకు కేంద్ర ప్రభుత్వం రూ. 2 లక్షలు, రాష్ట్రం రూ. 5 లక్షల ఎక్స్‌గ్రేషియా ప్రకటించాయి.",
