        "category": "అంతర్జాతీయం",
        "leadParagraph": "తైవాన్ జలసంధి చుట్టూ చైనా సైన్యం అత్యాధునిక యుద్ధ విమానాలు, క్షిపణి విధ్వంసక నౌకలతో భారీ చుట్టుముట్టడి చర్యలను ప్రారంభించింది.",
        "bodyContent": "చైనా దుందుడుకు సైనిక విన్యాసాలను అమెరికా, జపాన్ దేశాలు తీవ్రంగా ఖండించాయి. తైవాన్ సార్వభౌమాధికారానికి భంగం కలిగిస్తే చూస్తూ ఊరుకోబోమని స్పష్టం చేయడంతో ఉద్రిక్తతలు నెలకొన్నాయి. పసిఫిక్ సముద్ర మార్గంలో వాణిజ్య నౌకల రాకపోకలపై తీవ్ర ప్రభావం పడటంతో ప్రపంచ స్టాక్ మార్కెట్లు కుదేలయ్యాయి. శాంతిభద్రతలకు విఘాతం కలగకుండా సమన్వయం పాటించాలని అంతర్జాతీయ సమాజం విజ్ఞప్తి చేసింది.",
