        "tenantId": "tenant-metro-chronicle",
        "newsId": "art-te-007b",
        "articleTitle": "కాంగ్రెస్‌కు రాజగోపాల్ రాం..రాం! మునుగోడు ఎమ్మెల్యే సంచలనం",
        "headlineHighlight": "రాం..రాం!",
        "subheadline": "అనుచరులతో అత్యవసర భేటీ.. త్వరలోనే భవిష్యత్ కార్యాచరణ ప్రకటిస్తానని స్పష్టీకరణ",
        "byline": "రాజకీయ ప్రతినిధి, హైదరాబాద్",
        "category": "రాష్ట్రీయం",
        "leadParagraph": "మునుగోడు కాంగ్రెస్ ఎమ్మెల్యే కోమటిరెడ్డి రాజగోపాల్ రెడ్డి పార్టీ ప్రాథమిక సభ్యత్వానికి రాజీనామా చేస్తున్నట్లు ప్రకటించారు.",
        "bodyContent": "తెలంగాణ కాంగ్రెస్ నాయకత్వ వైఖరిపై ఆయన తీవ్ర విమర్శలు గుప్పించారు. తన నియోజకవర్గ ప్రజల ఆత్మగౌరవాన్ని కాపాడేందుకే ఈ కఠిన నిర్ణయం తీసుకున్నానని స్పష్టం చేశారు. అధిష్టానం వద్ద పదే పదే మొరపెట్టుకున్నా ప్రజా సమస్యల పరిష్కారంలో నిధుల కేటాయింపు జరగలేదని ఆరోపించారు. మునుగోడు సమగ్ర వికాసం కోసం ఎంతటి త్యాగానికైనా సిద్ధమని, ప్రజల అభిప్రాయం మేరకే తదుపరి రాజకీయ అడుగులు వేస్తానని తెలిపారు. ఈ సందర్భంగా అనుచరులు, నియోజకవర్గ కార్యకర్తలు భారీగా తరలివచ్చి మద్దతు పలికారు. పార్టీలో అసలైన ఉద్యమకారులకు, సీనియర్ నాయకులకు ప్రాధాన్యం దక్కడం లేదని, కొందరు వ్యక్తుల చేతుల్లోనే పాలన బందీ అయిందని రాజగోపాల్ రెడ్డి తీవ్రస్థాయిలో ధ్వజమెత్తారు. నియోజకవర్గంలో సాగునీటి ప్రాజెక్టులు, రోడ్ల అభివృద్ధి పనులకు బడ్జెట్ విడుదల చేయకుండా అణగదొక్కే ప్రయత్నం చేస్తున్నారని విమర్శించారు. తనను నమ్ముకున్న కార్యకర్తల ఆత్మగౌరవానికి భంగం వాటిల్లకుండా త్వరలోనే మునుగోడులో భారీ బహిరంగ సభ ఏర్పాటు చేసి భవిష్యత్ కార్యాచరణ ప్రకటిస్తానని స్పష్టం చేశారు.",
