        "leadParagraph": "రాష్ట్రంలో రైతాంగ సమస్యలను పరిష్కరించడంలో ప్రభుత్వం పూర్తిగా విఫలమైందని విపక్ష నేతలు విమర్శించారు.",
        "bodyContent": "వ్యవసాయ రంగానికి నిరంతర విద్యుత్, సకాలంలో ఎరువులు సరఫరా చేయడంలో యంత్రాంగం నిర్లక్ష్యం వహిస్తోందని విమర్శించారు. రుణమాఫీ హామీని నూరు శాతం షరతులు లేకుండా అమలు చేయాలని డిమాండ్ చేశారు. ఇటీవల వర్షాలకు దెబ్బతిన్న పంట నష్టపరిహారాన్ని వెంటనే రైతు ఖాతాల్లో జమ చేయాలని, లేనిపక్షంలో ఆందోళనలు తీవ్రతరం చేస్తామని హెచ్చరించారు.",
