        "pageId": "page-ed-andhra-prabha-today-1",
        "tenantId": "tenant-metro-chronicle",
        "newsId": "art-te-011",
        "articleTitle": "అమరావతి పునర్నిర్మాణ పనులకు నేడే అంకురార్పణ",
        "headlineHighlight": "అమరావతి",
        "subheadline": "హైకోర్టు, సచివాలయ సముదాయాలతో పాటు ఉద్యోగుల గృహనిర్మాణ ప్రాజెక్టులకు అంతర్జాతీయ టెండర్లు",
        "byline": "ప్రత్యేక ప్రతినిధి, అమరావతి",
        "category": "రాష్ట్రీయం",
        "leadParagraph": "ప్రజా రాజధాని అమరావతి నిర్మాణ పనులను వేగవంతం చేసేందుకు ప్రభుత్వం సరికొత్త కార్యాచరణను ప్రకటించింది.",
        "bodyContent": "రాజధాని ప్రాంతంలో అంతర్జాతీయ స్థాయి ఇన్‌ఫ్రాస్ట్రక్చర్, 12 వరుసల రహదారులు, అండర్‌గ్రౌండ్ డ్రైనేజీ వ్యవస్థలను ఏర్పాటు చేస్తున్నారు. భూములు త్యాగం చేసిన రైతులకు ప్రభుత్వం రుణపడి ఉందని, వారికి కేటాయించిన ప్లాట్లను అన్ని వసతులతో అభివృద్ధి చేసి వెంటనే అప్పగిస్తామని అధికారులు తెలిపారు. ప్రపంచ స్థాయి గ్రీన్ క్యాపిటల్‌గా రాజధాని నిర్మాణం పూర్తి కానుంది. హైకోర్టు శాశ్వత భవనాలు, సచివాలయ టవర్లు, హెచ్‌వోడీ కాంప్లెక్స్‌ల నిర్మాణాలకు అంతర్జాతీయ నిర్మాణ సంస్థలతో త్వరలోనే ఒప్పందాలు కుదుర్చుకోనున్నారు. వరద ముప్పు నివారణకు కొండవీటివాగు, పాలవాగు ఆధునికీకరణ పనులను ప్రాధాన్యతా క్రమంలో చేపడుతున్నారు. అమరావతిని స్టార్టప్ క్యాపిటల్‌గా తీర్చిదిద్దేందుకు ప్రముఖ ఐటీ, డేటా సెంటర్ కంపెనీలతో చర్చలు జరుపుతున్నట్లు సీఆర్‌డీఏ కమిషనర్ వెల్లడించారు. రైతులకు వార్షిక కౌలు సకాలంలో చెల్లించడంతో పాటు, పెండింగ్ కౌలు బకాయిలను సైతం విడుదల చేయాలని ప్రభుత్వం స్పష్టమైన ఆదేశాలు జారీ చేసింది. రాజధాని అనుసంధాన రహదారులైన సీడ్ యాక్సెస్ రోడ్డు విస్తరణ పనులకు గ్రీన్ సిగ్నల్ లభించింది. ప్రపంచ బ్యాంకు, ఏషియన్ డెవలప్‌మెంట్ బ్యాంక్ (ADB) సంయుక్తంగా రూ. 15,000 కోట్ల రుణ సహాయం అందించేందుకు సూత్రప్రాయంగా అంగీకరించాయి. నిర్మాణ పనుల పర్యవేక్షణకు డ్రోన్ ఆధారిత జియో-ట్యాగింగ్ విధానాన్ని అమలు చేస్తున్నారు. రాజధాని పరిధిలోని 29 గ్రామాల్లో మౌలిక సదుపాయాల కల్పనకు ప్రాధాన్యత ఇస్తూ, తాగునీరు, భూగర్భ విద్యుత్ లైన్ల ఏర్పాటును త్వరితగతిన పూర్తి చేయనున్నారు. అమరావతిని దేశంలోనే అత్యుత్తమ జీవన ప్రమాణాలు కలిగిన నగరంగా తీర్చిదిద్దేందుకు ప్రభుత్వం కట్టుబడి ఉందని మంత్రులు స్పష్టం చేశారు.",
        "x": 38,
        "y": 1344,
        "width": 776,
