        "articleTitle": "మురసు తుఫాను నష్టం రూ. 2,484.43 కోట్లు",
        "headlineHighlight": "రూ. 2,484.43 కోట్లు",
        "subheadline": "తీవ్రంగా దెబ్బతిన్న వరి, పత్తి పంటలు; తక్షణ సహాయం అందించాలని కేంద్ర బృందానికి విజ్ఞప్తి",
        "byline": "విపత్తుల విభాగం, అమరావతి",
        "category": "రాష్ట్రీయం",
        "leadParagraph": "ఇటీవల తీరం దాటిన తీవ్ర తుఫాను ధాటికి రాష్ట్రవ్యాప్తంగా రూ. 2,484.43 కోట్ల మేర ప్రాథమిక నష్టం వాటిల్లినట్లు ప్రభుత్వం ప్రాథమిక నివేదిక విడుదల చేసింది.",
        "bodyContent": "తీరప్రాంత జిల్లాల్లో వేలాది ఎకరాల్లో వరి, పత్తి, ఉద్యానవన పంటలు నీటమునిగి తీవ్ర నష్టం వాటిల్లింది. రహదారులు కొట్టుకుపోయి, విద్యుత్ స్తంభాలు నేలకొరిగాయి. సహాయక చర్యల కోసం ఎన్డీఆర్ఎఫ్, ఎస్డీఆర్ఎఫ్ బృందాలను రంగంలోకి దించారు. పంట నష్టపోయిన ప్రతి రైతును ప్రభుత్వం ఆదుకుంటుందని, తక్షణమే ఎన్యూమరేషన్ పూర్తి చేసి బ్యాంకు ఖాతాల్లో పరిహారం జమ చేయాలని జిల్లా కలెక్టర్లను సీఎం ఆదేశించారు. కేంద్రం నుంచి వెంటనే రూ. 1,000 కోట్ల ముందస్తు ఆర్థిక సాయం విడుదల చేయాలని కోరారు. దెబ్బతిన్న రోడ్లు, వంతెనల పునర్నిర్మాణానికి యుద్ధప్రాతిపదికన చర్యలు చేపట్టారు. విద్యుత్ పునరుద్ధరణ పనులను అధికారులు నిరంతరం పర్యవేక్షిస్తున్నారు. బాధిత కుటుంబాలకు నిత్యావసర సరుకులు పంపిణీ చేయడంతో పాటు వైద్య శిబిరాలను ఏర్పాటు చేసి అంటువ్యాధులు ప్రబలకుండా ముందుజాగ్రత్త చర్యలు చేపట్టారు. నష్ట తీవ్రతను పరిశీలించేందుకు కేంద్ర అధికారుల బృందం క్షేత్రస్థాయిలో పర్యటించి కేంద్ర హోం శాఖకు సమగ్ర నివేదిక సమర్పించనుంది.",
