        "newsId": "art-te-001",
        "articleTitle": "భారత్ సమ్మిట్‌కు: మోకాలడ్డు",
        "subheadline": "హైదరాబాద్‌కు అంతర్జాతీయ పెట్టుబడులు; కేంద్రం సహాయ నిరాకరణపై సీఎం రేవంత్ రెడ్డి పోరుబాట",
        "byline": "ఆంధ్రప్రభ బ్యూరో, హైదరాబాద్",
        "category": "రాష్ట్రీయం",
        "leadParagraph": "ఫార్మా, ఐటీ, ఏరోస్పేస్, పునరుత్పాదక ఇంధన రంగాల్లో రూ. 50 వేల కోట్ల పెట్టుబడులు రాష్ట్రానికి రావాల్సి ఉండగా, రాజకీయ కక్షసాధింపులతో అడ్డంకులు సృష్టించడం దేశ సమగ్రతకు చేటు చేస్తుందన్నారు.",
        "bodyContent": "రాష్ట్ర హక్కులను కాపాడటంలో రాజీపడే ప్రసక్తే లేదని తేల్చిచెప్పారు. తెలంగాణ ప్రజల ఆత్మగౌరవాన్ని దెబ్బతీసే ఏ ప్రయత్నాన్నీ సహించేది లేదని, అన్ని అడ్డంకులను అధిగమించి సదస్సును విజయవంతం చేసి తీరుతామని సీఎం పునరుద్ఘాటించారు. దేశ ఆర్థిక ప్రగతిలో భాగస్వామిగా ఉన్న తెలంగాణకు న్యాయబద్ధంగా రావాల్సిన నిధులు, అనుమతులను కేంద్రం వెంటనే విడుదల చేయాలని డిమాండ్ చేశారు. అంతర్జాతీయ పారిశ్రామికవేత్తలతో చేసుకున్న ఒప్పందాల అమలును వేగవంతం చేసేందుకు ప్రత్యేక నోడల్ ఏజెన్సీని ఏర్పాటు చేయాలని ప్రభుత్వం నిర్ణయించింది. ప్రపంచవ్యాప్తంగా గుర్తింపు పొందిన ఐటీ, ఫార్మా దిగ్గజాలకు అవసరమైన భూకేటాయింపులు, సింగిల్ విండో అనుమతులను రికార్డు సమయంలో మంజూరు చేస్తామని సీఎం ప్రకటించారు. తెలంగాణ అభివృద్ధిని అడ్డుకోవాలని చూసే శక్తులకు ప్రజలే తగిన బుద్ధి చెబుతారని హెచ్చరించారు.",
        "x": 38,
        "y": 80,
        "width": 619,
        "height": 440,
