        "newsId": "art-te-004",
        "articleTitle": "నా ఫోన్ ట్యాప్ చేస్తున్నారు: రాహుల్ సంచలనం",
        "subheadline": "పెగాసస్ తరహా స్పైవేర్ నిఘాపై సుప్రీంకోర్టు స్వతంత్ర విచారణకు కాంగ్రెస్ అగ్రనేత డిమాండ్",
        "byline": "ప్రత్యేక ప్రతినిధి, న్యూఢిల్లీ",
        "category": "జాతీయం",
        "leadParagraph": "దేశవ్యాప్తంగా ప్రతిపక్ష నేతలు, స్వతంత్ర జర్నలిస్టులు, న్యాయమూర్తుల ఫోన్లపై సైతం కన్నేసి ఉంచుతున్నారని రాహుల్ గాంధీ తీవ్ర ఆందోళన వ్యక్తం చేశారు.",
        "bodyContent": "ఇది రాజ్యాంగం ప్రసాదించిన పౌరహక్కుల తీవ్ర ఉల్లంఘనేనని స్పష్టం చేశారు. అంతర్జాతీయ దర్యాప్తు సంస్థల నివేదికలను ఉటంకిస్తూ, దేశ భద్రత పేరుతో ప్రజాస్వామ్య మూలాలను పెకిలిస్తున్నారని దుయ్యబట్టారు. ఈ నిఘా రాజ్యాన్ని అంతమొందించే వరకు తమ పోరాటం ఆగదని స్పష్టం చేశారు. ప్రజాస్వామ్య పరిరక్షణ కోసం దేశవ్యాప్త పౌర ఉద్యమాన్ని నిర్మిస్తామని హెచ్చరించారు. పార్లమెంట్‌లో అన్ని విపక్షాలను కలుపుకుని ఉమ్మడి పోరాటం చేస్తామని రాహుల్ గాంధీ స్పష్టం చేశారు. ఎన్నికల వేళ ప్రతిపక్షాల వ్యూహాలను పసిగట్టేందుకు నిఘా విభాగాలు దుర్వినియోగం అవుతున్నాయని, దీనికి బాధ్యులైన వారిని చట్టం ముందు నిలబెట్టే వరకు విశ్రమించబోమన్నారు.",
