        "placementId": "pl-p2-budget-agri",
        "editionId": "ed-andhra-prabha-today",
        "pageId": "page-ed-andhra-prabha-today-2",
        "tenantId": "tenant-metro-chronicle",
        "newsId": "art-te-p2-004",
        "articleTitle": "కేంద్ర బడ్జెట్ కేటాయింపులు: వ్యవసాయ రంగానికి పెద్దపీట",
        "subheadline": "డిజిటల్ అగ్రి మిషన్‌కు రూ. 25,000 కోట్లు; రైతులకు సున్నా వడ్డీ పంట రుణాలు.",
        "byline": "ఆర్థిక ప్రతినిధి, న్యూఢిల్లీ",
        "category": "జాతీయం",
        "leadParagraph": "దేశంలో గ్రామీణ ఆర్థిక వ్యవస్థను బలోపేతం చేయడమే ధ్యేయంగా కేంద్ర వ్యవసాయ బడ్జెట్‌లో రికార్డు స్థాయిలో కేటాయింపులు జరిగాయి.",
        "bodyContent": "సన్న, చిన్నకారు రైతులకు కిసాన్ క్రెడిట్ కార్డుల ద్వారా సున్నా వడ్డీతో రూ. 3 లక్షల వరకు రుణాలు అందించే పథకాన్ని విస్తరించారు. ప్రకృతి వ్యవసాయాన్ని ప్రోత్సహించేందుకు రైతులకు హెక్టారుకు రూ. 10,000 చొప్పున ప్రోత్సాహకం అందించనున్నారు. దేశవ్యాప్తంగా ప్రతి జిల్లాలో అధునాతన కోల్డ్ స్టోరేజీలు, గిడ్డంగుల నిర్మాణానికి వంద శాతం సబ్సిడీని ప్రకటించారు. డ్రోన్ల ద్వారా పురుగుమందుల పిచికారీకి మహిళా స్వయం సహాయక సంఘాలకు ప్రత్యేక శిక్షణ ఇస్తున్నారు. నూతన పారిశ్రామిక పాలసీ ద్వారా గ్లోబల్ ఇన్వెస్టర్లకు సింగిల్ విండో అనుమతులు, మౌలిక సదుపాయాల కల్పనలో రాష్ట్రం దేశంలోనే ప్రథమ స్థానంలో నిలిచింది. పారిశ్రామిక కారిడార్లలో నిరంతర విద్యుత్, రవాణా సదుపాయాలు సమకూర్చారు. స్థానిక నిరుద్యోగ యువతకు పరిశ్రమల అవసరాలకు తగినట్లుగా నైపుణ్యాభివృద్ధి శిక్షణ అందిస్తున్నారు. దీనివల్ల వలసలు తగ్గి సొంత జిల్లాలోనే స్థిరమైన ఉపాధి లభించే వాతావరణం ఏర్పడిందని ఆర్థిక నిపుణులు విశ్లేషిస్తున్నారు. చిన్న తరహా పరిశ్రమలకు (MSME) సులభతర రుణాలు, మార్కెటింగ్ సదుపాయాలు కల్పించేందుకు ప్రభుత్వం సరికొత్త క్లస్టర్లను అభివృద్ధి చేస్తోంది. రానున్న ఐదేళ్లలో పారిశ్రామిక ఎగుమతులు రెట్టింపు కావడమే లక్ష్యంగా పెట్టుకున్నారు. నూతన పారిశ్రామిక పాలసీ ద్వారా గ్లోబల్ ఇన్వెస్టర్లకు సింగిల్ విండో అనుమతులు, మౌలిక సదుపాయాల కల్పనలో రాష్ట్రం దేశంలోనే ప్రథమ స్థానంలో నిలిచింది. పారిశ్రామిక కారిడార్లలో నిరంతర విద్యుత్, రవాణా సదుపాయాలు సమకూర్చారు.",
