        "tenantId": "tenant-metro-chronicle",
        "newsId": "art-te-p2-005",
        "articleTitle": "భారత న్యాయ సంహిత: డిజిటల్ సాక్ష్యాల స్వీకరణలో నూతన మార్గదర్శకాలు",
        "subheadline": "నేర పరిశోధనలో సైబర్ ఫోరెన్సిక్స్ కీలకం; కేసుల దర్యాప్తులో వీడియో రికార్డింగ్ తప్పనిసరి.",
        "byline": "లీగల్ డెస్క్, న్యూఢిల్లీ",
        "category": "జాతీయం",
        "leadParagraph": "దేశంలో నేర న్యాయ వ్యవస్థను ఆధునీకరించే క్రమంలో సరికొత్త భారత న్యాయ సంహిత (BNS) నిబంధనల ప్రకారం డిజిటల్ సాక్ష్యాల ధృవీకరణ నిబంధనలు కఠినతరం చేయబడ్డాయి.",
        "bodyContent": "పోలీసు స్టేషన్లలో ఎఫ్ఐఆర్ నమోదు మొదలుకొని సంఘటన స్థలంలో పంచనామా నిర్వహణ వరకు ప్రతి దశలో ఆడియో, వీడియో రికార్డింగ్ తప్పనిసరి చేశారు. ఎలక్ట్రానిక్ డాక్యుమెంట్లు, క్లౌడ్ డేటా, సీసీటీవీ ఫుటేజీలను ఫోరెన్సిక్ సర్టిఫికేషన్‌తో మాత్రమే కోర్టులో ఆమోదిస్తారు. దీనివల్ల నిందితులకు కఠిన శిక్షలు పడేలా పకడ్బందీ న్యాయ ప్రక్రియ సాధ్యమవుతుందని కేంద్ర హోం శాఖ స్పష్టం చేసింది. సరిహద్దుల్లో ఏ క్షణమైనా ఎదురయ్యే సవాళ్లను తిప్పికొట్టేందుకు ఈ విమానాలలో అత్యాధునిక ఎలక్ట్రానిక్ కౌంటర్ మెజర్స్ (ECM) వ్యవస్థలను అమర్చారు. శత్రువుల రాడార్ల నిఘా నుంచి తప్పించుకునే స్టెల్త్ లక్షణాలు ఇందులో ఉండటం వల్ల వైమానిక పైలట్లకు తిరుగులేని ఆధిక్యత లభిస్తుంది. స్వదేశీ రక్షణ పరిశ్రమలకు వేల కోట్ల ఆర్డర్లు లభించడం ద్వారా వేలాది మంది ఇంజనీర్లు, చిన్న తరహా ఎంఎస్ఎంఈ పరిశ్రమలకు భారీ ప్రోత్సాహం లభించింది. విదేశీ దిగుమతులపై ఆధారపడే రోజులు పోయి స్వదేశీ ఆయుధ సంపత్తే దేశానికి రక్షణ కవచంగా నిలుస్తోంది. హిందుస్థాన్ ఏరోనాటిక్స్ లిమిటెడ్ (హెచ్‌ఏఎల్) ఇప్పటికే అత్యాధునిక రోబోటిక్ అసెంబ్లీ లైన్లను ఏర్పాటు చేసింది. తద్వారా నిర్ణీత గడువులోగా భారత వాయుసేనకు ఈ ఫైటర్ జెట్లను సరఫరా చేయనున్నట్లు ఉన్నతాధికారులు ధృవీకరించారు. సరిహద్దుల్లో ఏ క్షణమైనా ఎదురయ్యే సవాళ్లను తిప్పికొట్టేందుకు ఈ విమానాలలో అత్యాధునిక ఎలక్ట్రానిక్ కౌంటర్ మెజర్స్ (ECM) వ్యవస్థలను అమర్చారు. శత్రువుల రాడార్ల నిఘా నుంచి తప్పించుకునే స్టెల్త్ లక్షణాలు ఇందులో ఉండటం వల్ల వైమానిక పైలట్లకు తిరుగులేని ఆధిక్యత లభిస్తుంది.",
