        "newsId": "art-te-p2-007",
        "articleTitle": "తీరప్రాంత భద్రత: రక్షక దళానికి అత్యాధునిక గస్తీ నౌకలు",
        "subheadline": "సముద్ర సరిహద్దుల్లో 24 గంటల పటిష్ట నిఘా.",
        "byline": "రక్షణ కరస్పాండెంట్, విశాఖపట్నం",
        "category": "జాతీయం",
        "leadParagraph": "దేశ తూర్పు తీరప్రాంత భద్రతను పటిష్టం చేయడంలో భాగంగా భారత తీర రక్షక దళం (కోస్ట్ గార్డ్) సరికొత్త స్వదేశీ ఫాస్ట్ పెట్రోల్ నౌకలను ప్రారంభించింది.",
        "bodyContent": "తీరప్రాంత జలాల్లో అనుమానాస్పద కదలికలను గుర్తించేందుకు థర్మల్ ఇమేజింగ్ కెమెరాలు, డ్రోన్ లాంచర్లు అమర్చబడ్డాయి. మత్స్యకారుల రక్షణ కోసం శాటిలైట్ ట్రాకింగ్ ఎమర్జెన్సీ డివైస్‌లను అందజేశారు. సముద్ర కాలుష్య నివారణ పరికరాలను కూడా ఈ నౌకల్లో అమర్చారు. సరిహద్దుల్లో ఏ క్షణమైనా ఎదురయ్యే సవాళ్లను తిప్పికొట్టేందుకు ఈ విమానాలలో అత్యాధునిక ఎలక్ట్రానిక్ కౌంటర్ మెజర్స్ (ECM) వ్యవస్థలను అమర్చారు. శత్రువుల రాడార్ల నిఘా నుంచి తప్పించుకునే స్టెల్త్ లక్షణాలు ఇందులో ఉండటం వల్ల వైమానిక పైలట్లకు తిరుగులేని ఆధిక్యత లభిస్తుంది. స్వదేశీ రక్షణ పరిశ్రమలకు వేల కోట్ల ఆర్డర్లు లభించడం ద్వారా వేలాది మంది ఇంజనీర్లు, చిన్న తరహా ఎంఎస్ఎంఈ పరిశ్రమలకు భారీ ప్రోత్సాహం లభించింది. విదేశీ దిగుమతులపై ఆధారపడే రోజులు పోయి స్వదేశీ ఆయుధ సంపత్తే దేశానికి రక్షణ కవచంగా నిలుస్తోంది.",
