        "newsId": "art-te-p3-002",
        "articleTitle": "మహిళా సాధికారత: ఏటా 3 ఉచిత గ్యాస్ సిలిండర్ల పంపిణీకి శ్రీకారం",
        "subheadline": "దీపం పథకం ద్వారా కోటి 50 లక్షల కుటుంబాలకు లబ్ధి; బుకింగ్ చేసిన 48 గంటల్లో డెలివరీ.",
        "byline": "పౌరసరఫరాల విభాగం, అమరావతి",
        "category": "రాష్ట్రీయం",
        "leadParagraph": "రాష్ట్రంలోని పేద మహిళల జీవన ప్రమాణాలను మెరుగుపరచడమే లక్ష్యంగా ఎన్నికల హామీ మేరకు 'దీపం-2' పథకం కింద అర్హులైన ప్రతి కుటుంబానికి ఏడాదికి మూడు ఉచిత ఎల్పీజీ సిలిండర్ల పంపిణీ పథకం ప్రారంభమైంది.",
        "bodyContent": "ఈ పథకం అమలు కోసం రాష్ట్ర ప్రభుత్వం రూ. 2,684 కోట్ల నిధులను ప్రత్యేకంగా బడ్జెట్‌లో కేటాయించింది. లబ్ధిదారులు గ్యాస్ సిలిండర్ బుక్ చేసుకున్న 48 గంటల్లోగా వారి బ్యాంకు ఖాతాల్లోకి సిలిండర్ సబ్సిడీ మొత్తం నేరుగా జమ కానుంది. ఎటువంటి మధ్యవర్తులు లేకుండా అత్యంత పారదర్శకంగా ఈ ప్రక్రియ సాగేలా గ్రామ, వార్డు సచివాలయాల ద్వారా నిరంతర పర్యవేక్షణ ఏర్పాటు చేశారు. ఆధార్ ధృవీకరణ పూర్తయిన ప్రతి రేషన్ కార్డుదారు దీనికి అర్హులేనని ప్రభుత్వం స్పష్టం చేసింది. పారదర్శకమైన ప్రజా పాలనను అందించడమే ప్రభుత్వ ప్రధాన లక్ష్యమని ఉన్నతాధికారులు స్పష్టం చేశారు. ప్రతి పథకం లబ్ధిదారుల ఎంపికలో రాజకీయ జోక్యం లేకుండా నేరుగా ఆధార్ ఆధారిత బయోమెట్రిక్ వెరిఫికేషన్ ద్వారా అర్హులందరికీ న్యాయం చేస్తున్నారు. గ్రామ, వార్డు సచివాలయాల స్థాయిలో పౌర సేవలను మరింత బలోపేతం చేసేందుకు ప్రత్యేక తనిఖీ బృందాలను రంగంలోకి దించారు. ప్రజల నుంచి వచ్చిన వినతులను వారం రోజుల్లోగా పరిష్కరించేలా ఎస్ఓపీ (స్టాండర్డ్ ఆపరేటింగ్ ప్రొసీజర్) ఖరారైంది.",
