        "articleTitle": "గుంటూరు ఆసియాలోనే అతిపెద్ద మిర్చి యార్డు: రికార్డు స్థాయిలో ఎగుమతులు",
        "subheadline": "క్వింటాల్ మిర్చి ధర రూ. 24,000లకు చేరిక; చైనా, యూరప్ దేశాల నుంచి భారీ డిమాండ్.",
        "byline": "వ్యవసాయ ప్రతినిధి, గుంటూరు",
        "category": "జిల్లా వార్తలు",
        "leadParagraph": "ఆసియా ఖండంలోనే అతిపెద్ద వ్యవసాయ మార్కెట్ అయిన గుంటూరు మిర్చి యార్డులో రికార్డు స్థాయి వ్యాపారం నమోదవుతోంది.",
        "bodyContent": "తేజ, దేవనూరు డీలక్స్ రకాల మిర్చికి అంతర్జాతీయ మార్కెట్లలో విపరీతమైన గిరాకీ ఏర్పడింది. నాణ్యమైన స్పైస్ బోర్డు సర్టిఫికేషన్‌తో మిర్చిని నేరుగా ఓడరేవులకు తరలించి ఎగుమతులు చేస్తున్నారు. రైతులకు వేలం ముగిసిన గంటలోనే ఈ-నామ్ ద్వారా వారి బ్యాంకు ఖాతాల్లో నగదు జమ అవుతోంది. యార్డులో రైతులకు బస చేసేందుకు ఏసీ డార్మిటరీలు, రూ. 5లకే భోజన సదుపాయం కల్పించారు. నూతన పారిశ్రామిక పాలసీ ద్వారా గ్లోబల్ ఇన్వెస్టర్లకు సింగిల్ విండో అనుమతులు, మౌలిక సదుపాయాల కల్పనలో రాష్ట్రం దేశంలోనే ప్రథమ స్థానంలో నిలిచింది. పారిశ్రామిక కారిడార్లలో నిరంతర విద్యుత్, రవాణా సదుపాయాలు సమకూర్చారు. స్థానిక నిరుద్యోగ యువతకు పరిశ్రమల అవసరాలకు తగినట్లుగా నైపుణ్యాభివృద్ధి శిక్షణ అందిస్తున్నారు. దీనివల్ల వలసలు తగ్గి సొంత జిల్లాలోనే స్థిరమైన ఉపాధి లభించే వాతావరణం ఏర్పడిందని ఆర్థిక నిపుణులు విశ్లేషిస్తున్నారు. చిన్న తరహా పరిశ్రమలకు (MSME) సులభతర రుణాలు, మార్కెటింగ్ సదుపాయాలు కల్పించేందుకు ప్రభుత్వం సరికొత్త క్లస్టర్లను అభివృద్ధి చేస్తోంది. రానున్న ఐదేళ్లలో పారిశ్రామిక ఎగుమతులు రెట్టింపు కావడమే లక్ష్యంగా పెట్టుకున్నారు. నూతన పారిశ్రామిక పాలసీ ద్వారా గ్లోబల్ ఇన్వెస్టర్లకు సింగిల్ విండో అనుమతులు, మౌలిక సదుపాయాల కల్పనలో రాష్ట్రం దేశంలోనే ప్రథమ స్థానంలో నిలిచింది. పారిశ్రామిక కారిడార్లలో నిరంతర విద్యుత్, రవాణా సదుపాయాలు సమకూర్చారు. స్థానిక నిరుద్యోగ యువతకు పరిశ్రమల అవసరాలకు తగినట్లుగా నైపుణ్యాభివృద్ధి శిక్షణ అందిస్తున్నారు. దీనివల్ల వలసలు తగ్గి సొంత జిల్లాలోనే స్థిరమైన ఉపాధి లభించే వాతావరణం ఏర్పడిందని ఆర్థిక నిపుణులు విశ్లేషిస్తున్నారు. చిన్న తరహా పరిశ్రమలకు (MSME) సులభతర రుణాలు, మార్కెటింగ్ సదుపాయాలు కల్పించేందుకు ప్రభుత్వం సరికొత్త క్లస్టర్లను అభివృద్ధి చేస్తోంది. రానున్న ఐదేళ్లలో పారిశ్రామిక ఎగుమతులు రెట్టింపు కావడమే లక్ష్యంగా పెట్టుకున్నారు. నూతన పారిశ్రామిక పాలసీ ద్వారా గ్లోబల్ ఇన్వెస్టర్లకు సింగిల్ విండో అనుమతులు, మౌలిక సదుపాయాల కల్పనలో రాష్ట్రం దేశంలోనే ప్రథమ స్థానంలో నిలిచింది. పారిశ్రామిక కారిడార్లలో నిరంతర విద్యుత్, రవాణా సదుపాయాలు సమకూర్చారు.",
